function CreateBeaches(mapref) {
  if (!DU.gameflags.getFlag("editor")) {
    for (let i=0;i<mapref.data.length;i++){ 
      for (let j=0;j<mapref.data[0].length;j++) {
        if (mapref.getName() === "ellusus") {
          if ((j>=100) && (j<=110) && (i>=30) && (i<=36)) { continue; }
          if ((j>=72) && (j<=89) && (i>=33) && (i<=40)) { continue; }
          if ((j>=94) && (j<=96) && (i>=88) && (i<=91)) { continue; }
          if ((j>=94) && (j<=120) && (i>=98) && (i<=124)) { continue; }
        }
        let tile = mapref.getTile(j,i);
        let name = tile.getTerrain().getName();
        if ((name === "Water") || (name === "Shallows") || name.includes("OceanWaterTransition") || name.includes("WaterShallowsTransition")) {
          let isCoast = 0;
          for (let k=-1;k<=1;k++) {
            for (let l=-1;l<=1;l++) {
              let checkx = j+k;
              let checky = i+l;
              let checktile = mapref.getTile(checkx,checky);
              if (checktile !== "OoB") {
                let checkforcoast = checktile.getTerrain();
                if ((checkforcoast.getName() !== "Ocean") && (checkforcoast.getName() !== "Water") && (checkforcoast.getName() !== "Shallows") && !checkforcoast.getName().includes("OceanWaterTransition") && !checkforcoast.getName().includes("WaterShallowsTransition")) {
                  if (!isCoast) {
                    isCoast=1;
                    tile.addLocalSound("sfx_ocean_waves",PC);
                  }
                  if (!checktile.getLocalSound()) {
                    checktile.addLocalSound("sfx_ocean_waves",PC);
                  }
                }
              }
            }
          }
        }
      }
    }
  }
}

